import { Module } from '@nestjs/common';
import { ClientsModule, Transport } from '@nestjs/microservices';
import { TrackController } from './track.controller';

@Module({
  imports: [
    ClientsModule.register([
      {
        name: 'ANALYTICS',
        transport: Transport.KAFKA,
        options: {
          client: { brokers: ['localhost:9092'] },
        },
      },
    ]),
  ],
  controllers: [TrackController],
})
export class AppModule {}

import { Body, Controller, Inject, Post } from '@nestjs/common';
import { ClientProxy } from '@nestjs/microservices';

@Controller('track')
export class TrackController {
  constructor(@Inject('ANALYTICS') private client: ClientProxy) {}

  @Post()
  track(@Body() event: { page: string }) {
    this.client.emit('page_view', event);
    return { message: `Đã ghi nhận lượt xem ${event.page}` };
  }
}

import { NestFactory } from '@nestjs/core';
import { Transport } from '@nestjs/microservices';
import { AppModule } from './app.module';

async function bootstrap() {
  const app = await NestFactory.createMicroservice(AppModule, {
    transport: Transport.KAFKA,
    options: {
      client: { brokers: ['localhost:9092'] },
      consumer: { groupId: 'analytics' },
    },
  });
  await app.listen();
}
bootstrap();

import { Controller } from '@nestjs/common';
import { EventPattern, Payload } from '@nestjs/microservices';

@Controller()
export class AnalyticsController {
  private views = 0;

  @EventPattern('page_view')
  handleView(@Payload() event: { page: string }) {
    this.views = this.views + 1;
    console.log(`📈 Lượt xem thứ ${this.views}: trang ${event.page}`);
  }
}
